"""Focused I1 glue proofs. Never invokes CI or a core/USB proof sweep."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys
import time

ROOT = Path(__file__).resolve().parents[4]
sys.path.insert(0, str(ROOT / 'tools'))
from formal import validate_job, assertion_names

# Reviewed emitted property inventory, including inherited module assertions.
# The test harnesses bind architectural meanings to these autogenerated names.
INVENTORY = {
    'error': {'SocI1Formal': 4, 'SocDrainCredit': 2},
    'slot': {'SocI1Formal': 7, 'SocResetSlot': 4},
    'memory': {'SocI1Formal': 5, 'SocRetainedMemory': 2},
    'nested': {'SocNestedFormal': 1, 'SocNestedDrain': 1},
}
HARNESS_BINDINGS = {
    'SocI1Formal.scala': '5ee514714cc97144c9bd4a1c1fc937e9416b1f6ea69356442ab5d7fd879aba2e',
    'SocNestedFormal.scala': 'aa13715cc1521a99a6e238fe388be4e14664254e41de3313c7d9e26894f0d195',
}


def checked_faults(log, allowed, required):
    # Keep flattened hierarchy: credit.assert... is a different obligation
    # from the identically named assertion in the harness itself.
    failures = set(re.findall(r'Assert failed in [\w.]+: ([\w.]+assert__\w+|assert__\w+)', log))
    if not required <= failures <= allowed:
        raise RuntimeError(f'Fault identity mismatch: {sorted(failures)}')
    return sorted(failures)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--block', choices=tuple(INVENTORY), required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    output = (ROOT / args.output).resolve()
    output.relative_to(ROOT / 'build')
    output.mkdir(parents=True, exist_ok=False)
    sources = [ROOT / 'hw/top/reference/src/main/scala/deadhorse/top/SocI1Support.scala',
               ROOT / 'hw/top/reference/src/main/scala/deadhorse/top/SocDescription.scala',
               ROOT / 'hw/top/reference/src/main/scala/deadhorse/top/SocNestedDrain.scala',
               ROOT / 'hw/ip/bus/src/main/scala/deadhorse/bus/BusFabric.scala',
               *sorted((ROOT / 'hw/lib/src/main/scala').rglob('*.scala')),
               *sorted((ROOT / 'hw/ip/sram/src/main/scala').rglob('*.scala')),
               Path(__file__), Path(__file__).with_name('SocI1Formal.scala'),
               Path(__file__).with_name('SocNestedFormal.scala'),
               ROOT / 'build/t20/map/soc.json', ROOT / 'tools/formal.py',
               ROOT / 'tools/sbt.py', ROOT / 'build.sbt', ROOT / 'tools/env/lock.json',
               *sorted((ROOT / 'project').glob('*'))]
    sources = [p for p in sources if p.is_file()]
    def snapshot():
        return {str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest() for p in sources}
    receipt = dict(status='running', block=args.block,
                   commit=subprocess.check_output(['git', 'rev-parse', 'HEAD'], text=True).strip(),
                   source_sha256=snapshot(), timeout_seconds=120, cover_depth=32,
                   assumptions=['reset_n and peerReset_n low initially; arbitrary thereafter',
                                'Generated one-outstanding requester holds payload/request through acceptance'],
                   scope={'error': 'Real error target composed with destination drain credit',
                          'slot': 'Real reset slot with ResetRelease and finite error backend; sampled reset proof, no subcycle timing claim',
                          'memory': 'Full512-word C3 geometry admission/completion only; no memory data integrity or retention proof',
                          'nested': 'Real 128-edge child fabric and drain; legal variable-latency endpoint model; no upstream request restrictions'}[args.block],
                   runs=[])
    if args.block == 'nested':
        receipt['assumptions'][1] = 'Endpoint accepts once and replies after an arbitrarily chosen 0..255-edge delay'
    def run(command, name, timeout=180):
        start = time.monotonic()
        entry = dict(command=command, log=name+'.log')
        receipt['runs'].append(entry)
        try:
            with (output / (name+'.log')).open('w') as log:
                result = subprocess.run(command, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT, timeout=timeout)
            entry['returncode'] = result.returncode
            return result.returncode
        finally:
            entry['seconds'] = time.monotonic()-start
    try:
        for name, digest in HARNESS_BINDINGS.items():
            content = Path(__file__).with_name(name).read_bytes().replace(b'\r\n', b'\n')
            if hashlib.sha256(content).hexdigest() != digest:
                raise RuntimeError('Harness changed: review property identities before qualification')
        top = 'SocNestedFormal' if args.block == 'nested' else 'SocI1Formal'
        emission = (f'EmitSocNestedFormal {output}/emit' if args.block == 'nested' else
                    f'EmitSocI1Formal {args.block} {output}/emit')
        if run([sys.executable, 'tools/sbt.py',
                f'set hw / Compile / unmanagedSourceDirectories += file("{ROOT}/hw/top/reference/formal")',
                f'hw/runMain deadhorse.top.{emission}'], 'emit', 600):
            raise RuntimeError('Emission failed')
        expected_faults = {'error': {'assert__chisel3_builtin', 'assert__chisel3_builtin_1', 'credit.assert__chisel3_builtin_0'},
                           'slot': {'assert__chisel3_builtin', 'assert__chisel3_builtin_3', 'assert__chisel3_builtin_4'},
                           'memory': {'d.assert__chisel3_builtin', 'assert__chisel3_builtin_2'},
                           'nested': {'assert__chisel3_builtin', 'd.assert__chisel3_builtin'}}[args.block]
        required_faults = {'error': {'assert__chisel3_builtin_1', 'credit.assert__chisel3_builtin_0'},
                           'slot': {'assert__chisel3_builtin', 'assert__chisel3_builtin_3'},
                           'memory': {'d.assert__chisel3_builtin'},
                           'nested': {'d.assert__chisel3_builtin'}}[args.block]
        for variant, mode, engine in [('cover', 'cover', 'smtbmc z3'),
                                      ('corrupt', 'bmc', 'smtbmc z3'),
                                      ('correct', 'prove', 'abc pdr')]:
            files = sorted((output / 'emit' / variant).glob('*.sv'))
            if not files:
                raise RuntimeError('Missing emitted model')
            inventory = {p.name: re.findall(r'(assert__\w+):', p.read_text()) for p in files}
            count = sum(map(len, inventory.values()))
            normalized = {name.removesuffix('.sv'): props for name, props in inventory.items() if props}
            replacements = {'BadI1Slot': 'SocResetSlot', 'BadI1Memory': 'SocRetainedMemory',
                            'BadNestedDrain': 'SocNestedDrain'}
            normalized = {replacements.get(name, name): tuple(props) for name, props in normalized.items()}
            if normalized != {name: assertion_names(n) for name, n in INVENTORY[args.block].items()}:
                raise RuntimeError(f'Reviewed property inventory changed: {normalized}')
            covers = sum(len(re.findall(r'cover property', p.read_text())) for p in files)
            if covers != ((1 if args.block == 'error' else 2) if variant == 'cover' else 0):
                raise RuntimeError('Reviewed cover inventory changed')
            config = output / (variant+'.sby')
            config.write_text('\n'.join(['[options]', f'mode {mode}', 'depth 32', 'timeout 120', '',
                '[engines]', engine, '', '[script]',
                f'read_slang --top {top} '+' '.join(p.name for p in files),
                f'prep -top {top} -flatten',
                "fminit -seq reset_n 0,'z -seq peerReset_n 0,'z", 'async2sync', 'chformal -lower',
                f'select -assert-count {count} t:$assert', 'select -assert-count 2 t:$assume',
                *([f'select -assert-count {covers} t:$cover'] if variant == 'cover' else []),
                '', '[files]', *map(str, files), '']))
            code = run(['sby', '-d', str(output / variant), str(config)], variant)
            status = (output / variant / 'status').read_text().split()[0]
            receipt['runs'][-1].update(status=status, assertion_inventory=inventory, covers=covers)
            failures = validate_job(output / variant, 'negative' if variant == 'corrupt' else mode, code, status)
            if variant == 'corrupt':
                failures = checked_faults((output / variant / 'logfile.txt').read_text(), expected_faults, required_faults)
            if failures:
                receipt['runs'][-1]['failed_properties'] = failures
            print(f'PASS I1 {args.block} {variant}: {status}', flush=True)
        if snapshot() != receipt['source_sha256']:
            raise RuntimeError('Sources changed during proof')
        receipt['status'] = 'pass'
    except Exception as error:
        receipt.update(status='unresolved' if isinstance(error, subprocess.TimeoutExpired) or 'TIMEOUT' in str(error) else 'failed',
                       error=str(error))
        raise
    finally:
        receipt['artifact_sha256'] = {str(p.relative_to(output)): hashlib.sha256(p.read_bytes()).hexdigest()
                                     for p in sorted(output.rglob('*')) if p.is_file() and p != output / 'result.json'}
        (output / 'result.json').write_text(json.dumps(receipt, indent=2)+'\n')


if __name__ == '__main__':
    main()
